                timeout=60000,
            )
            page.wait_for_timeout(2500)
            info["forced_seller_url"] = True
    except Exception as e:  # noqa: BLE001
        info["force_error"] = str(e)

    info["after"] = {"url": page.url, "title": page.title()}
